#include <stdio.h>
#include <string.h>

void inverse(char *str, int len) {
    for (int i = 0, j = len - 1; i < j; i++, j--) {
        char ch = str[i];
        str[i] = str[j];
        str[j] = ch;
    }
}

int main() {
    char str[100] = "ABCDEFGH";
    int len = strlen(str);
    inverse(str, len);
    for (int i = 1; i < len; i += 2) {
        printf("%c", str[i]);
    }
    return 0;
}

class Parent {
    int x, y;
    Parent(int x, int y) { // ①
        this.x = x;
        this.y = y;
    }
    int getX() { // ②
        return x*y;
    }
}
class Child extends Parent {
    int x;
    Child(int x) { // ③
        super(x+1, x);
        this.x = x;
    }
    int getX(int n) { // ④
        return super.getX() + n;
    }
}
public class Main {
    public static void main(String[] args) { // ⑤
        Parent parent = new Child(10); // ⑥
        System.out.println(parent.getX()); // ⑦
    }
}

